class ErrTransport(Exception):
    """Base class for exceptions related to RUFF"""


class ErrTransportTimeout(ErrTransport):
    """ErrTransport"""

    def __init__(self, err_data=None):
        """Init ErrTransportTimeout"""
        super(ErrTransportTimeout, self).__init__(err_data)


class ErrRemoteEndpointDisconnected(ErrTransport):
    """ErrRemoteEndpointDisconnected"""
    def __init__(self, err_data):
        """Init ErrRemoteEndpointDisconnected"""
        super(ErrRemoteEndpointDisconnected, self).__init__(str(err_data))
        self.err = err_data


class ErrRemoteEndpointDead(ErrTransport):
    """ErrRemoteEndpointDead"""
    def __init__(self, err_data):
        """Init ErrRemoteEndpointDead"""
        super(ErrRemoteEndpointDead, self).__init__(str(err_data))
        self.err = err_data


